    current_time = state['current_time']

    # Base priority from lot weight and urgency
    base = task.weight * 100.0

    # HOT lot deadline handling (highest priority)
    if task.priority.value == 4 and task.deadline is not None:
        slack = task.deadline - current_time
        if slack < 0:
            base += 5000.0  # Already late, absolute priority
        elif slack < 1.0:
            base += 3000.0  # Critical urgency
        elif slack < 3.0:
            base += 1500.0  # Very urgent
        elif slack < 6.0:
            base += 500.0   # Somewhat urgent

    # Non-litho preference based on litho congestion
    if is_litho:
        litho_congestion = state['litho_queue']
        if litho_congestion > 8:
            base -= 3000.0  # Heavy penalty: avoid litho when very congested
        elif litho_congestion > 5:
            base -= 2000.0  # Moderate penalty
        elif litho_congestion > 3:
            base -= 1000.0  # Light penalty
        elif litho_congestion <= 1 and state['litho_utilization'] < 0.6:
            base += 500.0   # Bonus: run litho when idle
    else:
        # Bonus for non-litho steps, especially when litho is busy
        if state['litho_queue'] > 5:
            base += 1500.0  # Strong preference to clear non-litho work
        elif state['litho_queue'] > 3:
            base += 750.0   # Moderate preference

    # Remaining steps bonus (prefer nearly-finished lots for throughput)
    remaining_bonus = -task.remaining_steps * 20.0

    # Wait time fairness (but less weight than urgency)
    wait_bonus = task.queue_wait_time * 3.0

    return base + remaining_bonus + wait_bonus

def priority(task, state):
    # Dynamic Bottleneck Pressure Relief (DBPR)
    # Core idea: Actively relieve litho pressure by boosting non-litho lots
    # when litho is congested, while using slack-based HOT lot management

    score = 0.0

    # Determine next step type
    step_in_cycle = task.remaining_steps % 5
    going_to_litho = (step_in_cycle == 0 and task.remaining_steps > 0)

    # --- Base score: LWKR with dynamic weighting ---
    score -= task.estimated_remaining * 0.15

    # --- HOT lot deadline management ---
    if task.priority.value == 4:
        if task.deadline is not None:
            slack = task.deadline - state['current_time']
            if slack < 0:
                score += 3000  # Already late
            elif slack < 3:
                score += 2500
            elif slack < 8:
                score += 2000
            elif slack < 15:
                score += 1000
            else:
                score += 400
        else:
            score += 500

    # --- URGENT lots ---
    elif task.priority.value == 3:
        score += 200

    # --- Aging with priority weighting ---
    age_bonus = task.queue_wait_time * (0.5 if task.priority.value >= 3 else 0.2)
    score += age_bonus

    # --- Bottleneck pressure management ---
    litho_queue = state.get('litho_queue', 0)
    litho_util = state.get('litho_utilization', 0.5)

    if going_to_litho:
        # Penalty increases with litho congestion
        if litho_queue > 8:
            score -= 800
        elif litho_queue > 5:
            score -= 500
        elif litho_queue > 3:
            score -= 200
        elif litho_util > 0.9:
            score -= 100

        # Override for HOT lots that are critical
        if task.priority.value == 4 and task.deadline is not None:
            slack = task.deadline - state['current_time']
            if slack < 2:
                score += 1500  # Emergency override
            elif slack < 5:
                score += 800
    else:
        # Boost non-litho lots based on their machine utilization
        machine_util = None
        if step_in_cycle == 1:  # ETCH
            machine_util = state.get('etch_utilization', 0.5)
        elif step_in_cycle == 2:  # DEPO
            machine_util = state.get('depo_utilization', 0.5)
        elif step_in_cycle == 3:  # CLEAN
            machine_util = state.get('clean_utilization', 0.5)
        elif step_in_cycle == 4:  # INSPECT
            machine_util = state.get('inspect_utilization', 0.5)

        if machine_util is not None:
            if machine_util < 0.3:
                score += 300  # Starving machine
            elif machine_util < 0.5:
                score += 150
            elif machine_util > 0.85:
                score -= 100  # Avoid overloading other machines

    # --- Global load balancing ---
    total_queue = state.get('queue_length', 0)
    if total_queue < 10:
        # System is underutilized - push everything through
        score += task.queue_wait_time * 0.5
    elif total_queue > 25:
        # Heavy load - prioritize by value
        if task.priority.value == 4:
            score += 300
        elif task.priority.value == 3:
            score += 150

    # --- Fairness boost for long-waiting lots ---
    if task.queue_wait_time > 10:
        score += 200
    elif task.queue_wait_time > 5:
        score += 100

    return score

